// KMI MASTER 002.05 — Akıllı Ana Sayfa: öncelik ve tazelik sıralaması (saf fonksiyon; ağ/veritabanı yok).
// Girdi: görev satırları {id,status,dueAt,createdAt,autoGenerated,requirementsDone,requirementsTotal,blocking}
// Çıktı: puanı en yüksek ilk; her satırda neden metni (Türkçe). Gerçek veri yoksa uydurma değer üretmez.
const DAY = 86400000;
export function rankHomeItems(items, now = new Date()) {
  const t = now.getTime();
  const out = [];
  for (const it of items ?? []) {
    if (!it || ['COMPLETED', 'CANCELLED'].includes(it.status)) continue;
    let score = 0; const why = [];
    const due = it.dueAt ? Date.parse(it.dueAt) : NaN;
    if (Number.isFinite(due)) {
      const d = (due - t) / DAY;
      if (d < 0) { score += 100 + Math.min(50, Math.abs(d) * 5); why.push(`${Math.ceil(Math.abs(d))} gün gecikmiş`); }
      else if (d <= 1) { score += 60; why.push('bugün/yarın bitiyor'); }
      else if (d <= 3) { score += 30; why.push('3 gün içinde'); }
    }
    if (it.blocking) { score += 40; why.push('üretimi bekletiyor'); }
    if (it.autoGenerated && it.requirementsTotal > 0 && it.requirementsDone < it.requirementsTotal) { score += 10; why.push(`${it.requirementsDone}/${it.requirementsTotal} gereksinim tamam`); }
    const created = it.createdAt ? Date.parse(it.createdAt) : NaN;
    const stale = Number.isFinite(created) ? Math.min(20, Math.floor((t - created) / DAY)) : 0; // tazelik: eski açık iş yavaşça öne çıkar
    if (stale > 0) { score += stale; why.push(`${stale} gündür açık`); }
    out.push({ ...it, score, why: why.length ? why.join(' · ') : 'normal öncelik' });
  }
  return out.sort((a, b) => b.score - a.score || String(a.id).localeCompare(String(b.id)));
}
